#!/usr/bin/env bash
# scripts/audit/manifest-parity.sh — Family 2 of /audit.
#
# v1 scope: MCP tool permission parity between Claude and Auggie configures.
# The `mcp__ductus__*` entries are deterministically generated by
# scripts/gen-configure-mcp.sh from framework/runtime-tools.txt and must
# be in perfect agreement across both agent files. A drift here means
# either the generator failed silently or someone hand-edited a configure
# file. High-signal, zero-noise.
#
# Out of v1 scope (deferred to follow-on scenarios):
#
#   * Installer file list — retired, not deferred. This sub-check compared
#     the file lists of two installer paths. The second was a hand-
#     maintained, ductus-specific init command with no framework/commands/
#     source; it was retired on 2026-09-15, so /ductus is now the only path
#     that scaffolds a project and there is no second manifest to diff
#     against. The sub-check has no subject rather than a hard extraction
#     problem. See 026 AC4.
#
#   * Non-MCP permission parity (Bash↔launch-process, Edit↔str-replace-editor,
#     Write↔save-file, view↔Read, grep-search↔Grep, etc.). The Claude
#     permission set is intentionally broader than Auggie's in several
#     places (different hook integration, different fallback paths); a
#     literal diff produces high false-positive noise. Needs a hand-
#     maintained tool-name correspondence table — captured for a future
#     scenario after `/audit` v1 has been live and the desired tightness
#     emerges from real maintenance experience.

set -uo pipefail
# shellcheck source-path=SCRIPTDIR source=lib.sh
. "$(dirname "${BASH_SOURCE[0]}")/lib.sh" || exit 1
audit_family manifest-parity

# Extract the set of MCP tool names from each agent's configure file,
# stripping the agent-specific prefix so the sets are directly comparable.
# Claude uses `mcp__ductus__name` (double-underscore); Auggie uses
# `mcp:ductus:name` (colon). Normalize both to just the bare tool name
# (e.g., `read-spec`, `mark-task`).
# The lines between the generated-block markers: the canonical MCP entries.
# A retired entry elsewhere in the file (Claude's step 4) is not one.
generated_block() {
  sed -n '/<!-- generated:mcp-allow:start -->/,/<!-- generated:mcp-allow:end -->/p' "$1"
}

extract_claude_mcp() {
  local file="$1"
  generated_block "$file" | grep -oE '`mcp__ductus__[a-z-]+`' \
    | tr -d '`' \
    | sed -E 's/^mcp__ductus__//' \
    | sort -u
}

extract_auggie_mcp() {
  local file="$1"
  generated_block "$file" | grep -oE '"toolName": *"mcp:ductus:[a-z-]+"' \
    | sed -E 's/.*"mcp:ductus:([a-z-]+)".*/\1/' \
    | sort -u
}

claude_file="framework/bootstrap/configure/claude.md"
auggie_file="framework/bootstrap/configure/auggie.md"

for f in "$claude_file" "$auggie_file"; do
  if [ ! -f "$f" ]; then
    emit "$f" "configure source is missing — the permission sets cannot be compared" \
      "restore the file; a comparison that could not run must not exit like one that agreed"
    exit "$drift"
  fi
done

claude_mcp="$(extract_claude_mcp "$claude_file")"
auggie_mcp="$(extract_auggie_mcp "$auggie_file")"

# Fail closed on an empty extraction, the rule every family from 17 onward
# follows and ./README.md states as the contract: two empty sets compare
# equal, so a prefix spelling this script hardcodes independently of
# gen-configure-mcp.sh can stop matching on BOTH sides at once and the
# family reports agreement it never established. check-zero does not cover
# it — it compares the generator against the files, so a format change that
# moves together passes there and empties both greps here.
claude_count="$(printf '%s' "$claude_mcp" | grep -c . || true)"
auggie_count="$(printf '%s' "$auggie_mcp" | grep -c . || true)"
for pair in "$claude_file:$claude_count" "$auggie_file:$auggie_count"; do
  if [ "${pair##*:}" -eq 0 ]; then
    emit "${pair%:*}" "no mcp__ductus__ / mcp:ductus: entries extracted — the comparison had nothing to compare" \
      "re-run scripts/gen-configure-mcp.sh, or update this family extraction if the generated entry shape changed"
  fi
done
[ "$drift" -eq 0 ] || exit "$drift"

# The examined counts, so a clean exit says what it compared rather than
# asserting agreement in the abstract.
echo "manifest-parity: compared $claude_count MCP entr(ies) in $claude_file against $auggie_count in $auggie_file" >&2

only_claude="$(comm -23 <(printf '%s' "$claude_mcp") <(printf '%s' "$auggie_mcp"))"
only_auggie="$(comm -13 <(printf '%s' "$claude_mcp") <(printf '%s' "$auggie_mcp"))"

if [ -n "$only_claude" ]; then
  while IFS= read -r entry; do
    [ -z "$entry" ] && continue
    emit "framework/bootstrap/configure/auggie.md" "MCP permission only in Claude config: $entry" "re-run scripts/gen-configure-mcp.sh to resync the generated blocks"
  done <<< "$only_claude"
fi
if [ -n "$only_auggie" ]; then
  while IFS= read -r entry; do
    [ -z "$entry" ] && continue
    emit "framework/bootstrap/configure/claude.md" "MCP permission only in Auggie config: $entry" "re-run scripts/gen-configure-mcp.sh to resync the generated blocks"
  done <<< "$only_auggie"
fi

exit "$drift"
